    'sistema-solar': { n: 'Sistema solar', sub: 'diámetro de la órbita de Neptuno', d: 'La órbita de Neptuno abarca 60 unidades astronómicas: unas ocho horas luz de lado a lado.' },
    'dia-luz': { n: 'Un día luz', sub: 'distancia', d: 'Lo que recorre la luz en 24 horas: 25 900 millones de kilómetros. La sonda Voyager 1, tras casi medio siglo de viaje, apenas está a un día luz.' },
    'heliosfera': { n: 'Heliosfera', sub: 'diámetro aproximado', d: 'La burbuja que el viento solar infla alrededor del Sol. Las sondas Voyager la cruzaron a unas 120 unidades astronómicas y hoy viajan por el espacio interestelar.' },
    'm87': { n: 'M87*', sub: 'diámetro del horizonte de sucesos', d: 'El primer agujero negro fotografiado, en 2019. Con 6 500 millones de masas solares, su horizonte es más ancho que toda la órbita de Neptuno.' },
    'anio-luz': { n: 'Un año luz', sub: 'distancia', lab: '1 año', d: '9,46 billones de kilómetros. Como la luz tarda en llegarnos, mirar lejos es siempre mirar al pasado.' },
    'oort': { n: 'Nube de Oort', sub: 'diámetro estimado', d: 'Una envoltura de billones de cuerpos helados, cuna de los cometas de período largo. Su borde exterior podría llegar a un año luz y medio del Sol.' },
    'proxima': { n: 'Distancia a Próxima Centauri', sub: 'distancia', d: 'La estrella más cercana al Sol está a 4,24 años luz. Con un cohete actual, el viaje duraría decenas de miles de años.' },
    'cangrejo': { n: 'Nebulosa del Cangrejo', sub: 'diámetro', d: 'Los restos de una supernova que los astrónomos chinos anotaron en el año 1054. Once años luz de ancho y todavía creciendo a 1 500 kilómetros por segundo.' },
    'orion': { n: 'Nebulosa de Orión', sub: 'diámetro', d: 'Una guardería estelar visible a simple vista bajo el cinturón de Orión, a 1 350 años luz. Allí están naciendo estrellas ahora mismo.' },
    'burbuja': { n: 'Burbuja Local', sub: 'diámetro aproximado', d: 'Una cavidad de gas caliente y muy poco denso de unos 300 años luz, excavada por supernovas antiguas. El Sol viaja por su interior.' },
    'brazo': { n: 'Brazo de Orión', sub: 'anchura', d: 'El brazo espiral menor de la Vía Láctea donde vive el Sol: unos 3 500 años luz de ancho y 10 000 de largo.' },
    'nube-magallanes': { n: 'Gran Nube de Magallanes', sub: 'diámetro', d: 'Galaxia satélite de la Vía Láctea, visible desde el hemisferio sur como una mancha difusa. Unos 32 000 años luz de diámetro.' },
    'via-lactea': { n: 'Vía Láctea', sub: 'diámetro del disco', d: 'Nuestra galaxia: un disco de unos 100 000 años luz con entre 100 000 y 400 000 millones de estrellas. El Sol tarda 230 millones de años en darle una vuelta.' },
    'andromeda': { n: 'Galaxia de Andrómeda', sub: 'diámetro aproximado', d: 'La gran galaxia más próxima, de unos 220 000 años luz. Chocará con la Vía Láctea dentro de unos 4 500 millones de años.' },
    'dist-andromeda': { n: 'Distancia a Andrómeda', sub: 'distancia', d: '2,5 millones de años luz. Es el objeto más lejano visible a simple vista: su luz partió hace dos millones y medio de años.' },
    'virgo': { n: 'Cúmulo de Virgo', sub: 'diámetro', d: 'Más de mil galaxias a 54 millones de años luz. Su gravedad arrastra lentamente a nuestro Grupo Local.' },
    'grupo-local': { n: 'Grupo Local', sub: 'diámetro', d: 'El conjunto de unas 80 galaxias que incluye la Vía Láctea y Andrómeda, de unos 10 millones de años luz de diámetro.' },
    'bootes': { n: 'Vacío de Bootes', sub: 'diámetro', d: 'Una región casi vacía de 330 millones de años luz con apenas 60 galaxias conocidas. En un volumen normal habría miles.' },
    'laniakea': { n: 'Supercúmulo de Laniakea', sub: 'diámetro', d: '«Cielo inmenso» en hawaiano: el supercúmulo de 100 000 galaxias y 520 millones de años luz al que pertenecemos.' },
    'muralla': { n: 'Gran Muralla de Hércules-Corona Boreal', sub: 'longitud estimada', d: 'Candidata a mayor estructura conocida, de unos 10 000 millones de años luz. Que sea una estructura real y no un espejismo estadístico sigue en debate.' },
    'universo': { n: 'Universo observable', sub: 'diámetro', d: '93 000 millones de años luz de diámetro: todo lo que la luz ha tenido tiempo de mostrarnos en 13 800 millones de años. Más allá, nadie sabe.' },
